const now = new Date();

return {
  json: {
    dev: true,

    business_code: 'BARB001',

    channel: {
      type: 'WHATSAPP',
      provider: 'META'
    },

    customer: {
      external_user_id: 'DEV_CUSTOMER_001'
    },

    message: {
      external_message_id:
        `DEV_${Date.now()}`,

      idempotency_key:
        `DEV_IN_${Date.now()}`,

      type: 'text',

      text: 'mn vê aí se tem corte amanhã de tarde com o pedro',

      provider_timestamp:
        now.toISOString(),

      raw_payload: {
        source: 'DEV'
      }
    },

    received_at:
      now.toISOString()
  }
};

const envelope = $json;

const context =
  $('02 - CARREGAR CONTEXTO CORE').item.json.context ?? {};


// ======================================================
// EXTRAIR COMANDO DA IA / COMANDO ESTRUTURADO
// ======================================================

let command =
  envelope.structured_command
  ?? envelope.output?.[0]?.content
      ?.find(item => item.type === 'output_text')
      ?.text
  ?? null;

if (typeof command === 'string') {
  try {
    command = JSON.parse(command);
  } catch {
    command = null;
  }
}


// ======================================================
// ESTRUTURAS DE VALIDAÇÃO
// ======================================================

const errors = [];
const warnings = [];

if (!command || typeof command !== 'object') {
  errors.push('INVALID_AI_OUTPUT');
}


// ======================================================
// HELPERS
// ======================================================

const uuidRegex =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;


// ======================================================
// TIPOS E AÇÕES PERMITIDOS
// ======================================================

const allowedKinds = new Set([
  'BUSINESS_ACTION',
  'CONVERSATION',
  'NEED_INFORMATION',
  'HUMAN_HANDOFF'
]);

const allowedActions = new Set([
  'SEARCH_AVAILABILITY',
  'SELECT_SLOT',
  'CANCEL_APPOINTMENT',
  'RESCHEDULE_APPOINTMENT',
  'REBOOK_APPOINTMENT',
  'GET_APPOINTMENT',
  'JOIN_WAITLIST',
  'NONE'
]);

const kind =
  command?.kind ?? null;

const action =
  command?.action ?? 'NONE';


if (
  kind
  && !allowedKinds.has(kind)
) {
  errors.push('INVALID_KIND');
}


if (
  action
  && !allowedActions.has(action)
) {
  errors.push('INVALID_ACTION');
}


// ======================================================
// DIRECT RESPONSE
// ======================================================

let directResponse =
  typeof command?.direct_response === 'string'
    ? command.direct_response.trim()
    : null;

if (directResponse === '') {
  directResponse = null;
}


// BUSINESS_ACTION nunca pode responder antes do CORE.
if (
  kind === 'BUSINESS_ACTION'
  && directResponse !== null
) {
  warnings.push(
    'DIRECT_RESPONSE_IGNORED_FOR_BUSINESS_ACTION'
  );

  directResponse = null;
}


// Conversa / informação faltante / handoff
// precisam possuir mensagem pronta.
if (
  (
    kind === 'CONVERSATION'
    || kind === 'NEED_INFORMATION'
    || kind === 'HUMAN_HANDOFF'
  )
  && !directResponse
) {
  errors.push('DIRECT_RESPONSE_REQUIRED');
}


// Tudo que não for BUSINESS_ACTION
// deve usar action NONE.
if (
  kind !== 'BUSINESS_ACTION'
  && action !== 'NONE'
) {
  errors.push(
    'NON_BUSINESS_KIND_MUST_USE_NONE'
  );
}


// BUSINESS_ACTION deve ter ação real.
if (
  kind === 'BUSINESS_ACTION'
  && action === 'NONE'
) {
  errors.push(
    'BUSINESS_ACTION_REQUIRES_ACTION'
  );
}


// ======================================================
// CATÁLOGO REAL
// ======================================================

const services =
  Array.isArray(context.services)
    ? context.services
    : [];

const professionals =
  Array.isArray(context.professionals)
    ? context.professionals
    : [];

const serviceId =
  command?.arguments?.service_id
  ?? null;

const professionalId =
  command?.arguments?.professional_id
  ?? null;


// ======================================================
// VALIDAR SERVICE_ID
// ======================================================

let validatedService = null;

if (serviceId) {

  validatedService =
    services.find(
      service =>
        service.service_id === serviceId
    )
    ?? null;

  if (!validatedService) {
    errors.push('UNKNOWN_SERVICE_ID');
  }
}


// ======================================================
// VALIDAR PROFESSIONAL_ID
// ======================================================

let validatedProfessional = null;

if (professionalId) {

  validatedProfessional =
    professionals.find(
      professional =>
        professional.professional_id
        === professionalId
    )
    ?? null;

  if (!validatedProfessional) {
    errors.push('UNKNOWN_PROFESSIONAL_ID');
  }
}


// ======================================================
// SERVIÇO × PROFISSIONAL
// ======================================================

if (
  validatedService
  && validatedProfessional
) {

  const professionalAllowed =
    Array.isArray(
      validatedService.professionals
    )
    && validatedService.professionals.some(
      professional =>
        professional.professional_id
        === validatedProfessional.professional_id
    );

  if (!professionalAllowed) {
    errors.push(
      'PROFESSIONAL_DOES_NOT_PERFORM_SERVICE'
    );
  }
}


// ======================================================
// DATA
// ======================================================

const requestedDate =
  command?.arguments?.date
  ?? null;

const localDate =
  context.clock?.local_date
  ?? null;


if (
  requestedDate
  && !/^\d{4}-\d{2}-\d{2}$/.test(
    requestedDate
  )
) {
  errors.push('INVALID_DATE_FORMAT');
}


if (
  action === 'SEARCH_AVAILABILITY'
  && requestedDate
  && localDate
  && requestedDate < localDate
) {
  errors.push('DATE_IN_PAST');
}


// ======================================================
// SEARCH_AVAILABILITY
// ======================================================

if (
  kind === 'BUSINESS_ACTION'
  && action === 'SEARCH_AVAILABILITY'
) {

  if (!serviceId) {
    errors.push(
      'SEARCH_REQUIRES_SERVICE'
    );
  }

  if (!requestedDate) {
    errors.push(
      'SEARCH_REQUIRES_DATE'
    );
  }
}


// ======================================================
// SELECT_SLOT
// ======================================================

if (
  kind === 'BUSINESS_ACTION'
  && action === 'SELECT_SLOT'
) {

  const offer =
    context.active_offer ?? null;

  const optionNumber =
    command?.arguments?.option_number
    ?? null;


  if (!offer) {
    errors.push(
      'NO_ACTIVE_SLOT_OFFER'
    );
  }


  if (!optionNumber) {
    errors.push(
      'SELECT_SLOT_REQUIRES_OPTION'
    );
  }


  if (
    offer
    && optionNumber
  ) {

    const optionExists =
      Array.isArray(offer.options)
      && offer.options.some(
        option =>
          option.option_number
          === optionNumber
      );

    if (!optionExists) {
      errors.push(
        'UNKNOWN_SLOT_OPTION'
      );
    }
  }
}


// ======================================================
// REBOOK_APPOINTMENT
// ======================================================

if (
  kind === 'BUSINESS_ACTION'
  && action === 'REBOOK_APPOINTMENT'
) {

  const appointmentId =
    command?.arguments?.appointment_id
    ?? null;


  if (!appointmentId) {

    errors.push(
      'REBOOK_REQUIRES_APPOINTMENT'
    );

  } else if (
    typeof appointmentId !== 'string'
    || !uuidRegex.test(appointmentId)
  ) {

    errors.push(
      'INVALID_APPOINTMENT_ID'
    );
  }
}


// ======================================================
// CANCEL_APPOINTMENT
//
// Aqui validamos apenas formato.
// Autorização, dono do appointment e regras de horário
// continuam sendo responsabilidade do CORE.
// ======================================================

if (
  kind === 'BUSINESS_ACTION'
  && action === 'CANCEL_APPOINTMENT'
) {

  const appointmentId =
    command?.arguments?.appointment_id
    ?? null;


  if (!appointmentId) {

    errors.push(
      'CANCEL_REQUIRES_APPOINTMENT'
    );

  } else if (
    typeof appointmentId !== 'string'
    || !uuidRegex.test(appointmentId)
  ) {

    errors.push(
      'INVALID_APPOINTMENT_ID'
    );
  }
}


// ======================================================
// RESCHEDULE_APPOINTMENT
//
// Ainda não executamos o motor completo aqui,
// mas já protegemos appointment_id.
// ======================================================

if (
  kind === 'BUSINESS_ACTION'
  && action === 'RESCHEDULE_APPOINTMENT'
) {

  const appointmentId =
    command?.arguments?.appointment_id
    ?? null;


  if (!appointmentId) {

    errors.push(
      'RESCHEDULE_REQUIRES_APPOINTMENT'
    );

  } else if (
    typeof appointmentId !== 'string'
    || !uuidRegex.test(appointmentId)
  ) {

    errors.push(
      'INVALID_APPOINTMENT_ID'
    );
  }
}


// ======================================================
// GET_APPOINTMENT
// ======================================================

if (
  kind === 'BUSINESS_ACTION'
  && action === 'GET_APPOINTMENT'
) {

  const appointmentId =
    command?.arguments?.appointment_id
    ?? null;


  if (
    appointmentId
    && (
      typeof appointmentId !== 'string'
      || !uuidRegex.test(appointmentId)
    )
  ) {

    errors.push(
      'INVALID_APPOINTMENT_ID'
    );
  }
}


// ======================================================
// MISSING INFORMATION
// ======================================================

const missingInformation =
  Array.isArray(
    command?.missing_information
  )
    ? command.missing_information
    : [];


if (
  kind === 'NEED_INFORMATION'
  && missingInformation.length === 0
) {
  warnings.push(
    'NEED_INFORMATION_WITHOUT_MISSING_FIELDS'
  );
}


// ======================================================
// CONFIANÇA
// ======================================================

const confidence =
  Number(
    command?.confidence ?? 0
  );

const minimumConfidence =
  Number(
    context.ai_settings
      ?.minimum_intent_confidence
    ?? 0.7
  );


if (
  kind === 'BUSINESS_ACTION'
  && confidence < minimumConfidence
) {
  errors.push(
    'LOW_AI_CONFIDENCE_FOR_EXECUTION'
  );
}


// ======================================================
// DEFINIR ROTA ESTRUTURAL
// ======================================================

let route = 'INVALID';

if (errors.length === 0) {

  if (kind === 'BUSINESS_ACTION') {

    route = 'CORE';

  } else if (
    kind === 'CONVERSATION'
    || kind === 'NEED_INFORMATION'
  ) {

    route = 'DIRECT_RESPONSE';

  } else if (
    kind === 'HUMAN_HANDOFF'
  ) {

    route = 'HUMAN_HANDOFF';

  }
}


// ======================================================
// OUTPUT CANÔNICO V3
//
// action_args porque "arguments" dá problema
// em expressões do sandbox do n8n.
// ======================================================

return {
  json: {

    validated_command: {

      valid:
        errors.length === 0,

      executable:
        errors.length === 0
        && route === 'CORE',

      route,

      kind,

      intent:
        command?.intent
        ?? null,

      action,

      action_args: {
        ...(command?.arguments ?? {}),

        service_id:
          validatedService?.service_id
          ?? serviceId
          ?? null,

        professional_id:
          validatedProfessional?.professional_id
          ?? professionalId
          ?? null
      },

      service:
        validatedService,

      professional:
        validatedProfessional,

      missing_information:
        missingInformation,

      customer_meaning:
        command?.customer_meaning
        ?? '',

      direct_response:
        directResponse,

      confidence,

      minimum_confidence:
        minimumConfidence,

      errors,

      warnings
    },

    context
  }
};

const execution =
  $json.execution ?? {};

const validated =
  $('05 - VALIDAR COMANDO IA').item.json.validated_command ?? {};

const context =
  $('05 - VALIDAR COMANDO IA').item.json.context ?? {};

const originalInput =
  $('01 - NORMALIZAR ENTRADA').item.json;


// ======================================================
// RESPONSE ENGINE V3
// ======================================================

const systemInstruction = `
Você é o RESPONSE ENGINE da ML Automações.

Sua função é transformar fatos confirmados pelo Business Core em uma resposta
humana, natural, contextual, visualmente agradável e apropriada para WhatsApp.

Você NÃO decide regras empresariais.
Você NÃO executa operações.
Você NÃO altera fatos retornados pelo Business Core.

O campo core_execution contém a verdade operacional desta resposta.

=====================================================
PRINCÍPIO CENTRAL
=====================================================

Os FATOS vêm do Business Core.

A FORMA DE COMUNICAR vem de você.

Isso significa que você pode variar:
- linguagem;
- estrutura;
- grau de formalidade;
- tamanho;
- organização;
- maneira de apresentar a informação;
- uso moderado de emojis;
- escolha das palavras;
- tom de atendimento.

Mas você NUNCA pode alterar:
- horários;
- datas;
- preços;
- duração;
- serviços;
- profissionais;
- status de agendamento;
- disponibilidade;
- regras empresariais;
- resultado de operações.

=====================================================
VERDADE OPERACIONAL
=====================================================

Você NUNCA pode:

- inventar horários;
- inventar disponibilidade;
- inventar preços;
- inventar serviços;
- inventar profissionais;
- inventar duração;
- inventar promoções;
- afirmar que um agendamento foi criado sem confirmação do CORE;
- afirmar que algo foi cancelado sem confirmação do CORE;
- afirmar que algo foi remarcado sem confirmação do CORE;
- dizer que uma operação deu certo quando execution indicar erro;
- alterar informações retornadas pelo Business Core.

Se o CORE retornar:

status = CONFIRMED

você pode dizer que o horário ficou marcado ou confirmado.

Se retornar apenas HOLD,
não diga que o agendamento está definitivamente confirmado.

=====================================================
PERSONALIZAÇÃO
=====================================================

A resposta deve parecer escrita especificamente para aquele cliente
naquele momento.

Use sinais linguísticos observáveis como:

- idioma;
- formalidade;
- informalidade;
- objetividade;
- tamanho das mensagens;
- uso de abreviações;
- uso de gírias;
- uso de emojis;
- ritmo da conversa;
- maneira de fazer perguntas;
- histórico recente;
- perfil de comunicação armazenado.

Considere também:

customer.communication_profile
recent_messages
original_message

Não imite erros ortográficos do cliente.

Você pode ser informal sem escrever errado.

Não faça inferências sobre:
- idade;
- gênero;
- classe social;
- escolaridade;
- religião;
- etnia;
- saúde;
- personalidade psicológica;
- outras características sensíveis.

Adapte apenas aspectos observáveis da comunicação.

=====================================================
IDENTIDADE DA EMPRESA
=====================================================

Respeite os limites definidos em brand:

- assistant_name;
- brand_personality;
- default_treatment;
- minimum_formality;
- maximum_informality;
- allow_slang;
- emoji_max_per_message;
- response_guidelines;
- greeting_text;
- farewell_text.

A adaptação ao cliente nunca deve destruir a identidade da empresa.

=====================================================
IDIOMA
=====================================================

Responda preferencialmente no mesmo idioma predominante utilizado pelo cliente.

Se houver mistura de idiomas,
use o idioma predominante da conversa.

Preserve nomes próprios, serviços, profissionais e marcas.

=====================================================
NATURALIDADE
=====================================================

Não use um texto fixo.

Não responda sempre com a mesma estrutura.

Evite parecer:
- chatbot;
- URA;
- formulário;
- menu eletrônico;
- mensagem automática genérica.

Evite introduções repetitivas como:
"Perfeito!"
"Claro!"
"Tem sim!"

quando não forem naturais naquele contexto.

Não comece todas as mensagens da mesma maneira.

Você pode:
- ser direto;
- ser mais acolhedor;
- resumir;
- destacar a informação principal;
- usar pequenas quebras de linha;
- usar emoji quando adequado;
- fazer uma pergunta curta ao final.

=====================================================
WHATSAPP E EXPERIÊNCIA VISUAL
=====================================================

A resposta será usada no WhatsApp.

Priorize:
- leitura rápida;
- blocos curtos;
- boa hierarquia;
- poucas linhas;
- clareza;
- aparência organizada.

Evite paredes de texto.

Use quebras de linha quando melhorarem a leitura.

Emojis podem ser usados como apoio visual,
mas respeite brand.emoji_max_per_message.

Não use excesso de símbolos decorativos.

=====================================================
HORÁRIOS DISPONÍVEIS / SLOT_OFFER
=====================================================

Quando:

core_execution.result_type = SLOT_OFFER

e houver horários disponíveis:

O sistema exibirá os horários através de uma interface interativa
do WhatsApp, usando botões ou lista.

Portanto:

NÃO liste todos os horários dentro do campo text.

NÃO escreva:
"14h30, 14h45, 15h, 15h15..."

O sistema renderizará essas opções separadamente.

Sua função é escrever apenas uma introdução humana e contextual
para aparecer acima dos botões ou da lista.

A introdução pode mencionar, quando útil:

- serviço;
- profissional;
- dia;
- período;
- preço;
- duração;
- alguma observação curta.

Depois convide o cliente a escolher uma opção abaixo.

Exemplo informal:

"achei umas opções com o Pedro amanhã à tarde 👇
o corte fica R$ 30. vê qual horário encaixa melhor pra tu"

Exemplo neutro:

"Separei algumas opções com o Pedro para amanhã à tarde.
O corte fica R$ 30. Escolha abaixo o horário que funcionar melhor pra você 👇"

Exemplo mais formal:

"Encontrei horários disponíveis com o Pedro para amanhã à tarde.
Selecione abaixo o horário de sua preferência."

Esses exemplos são apenas referências de estilo.

NÃO os trate como templates.

Crie uma mensagem adequada ao cliente atual.

=====================================================
QUANDO NÃO HOUVER HORÁRIOS
=====================================================

Se o Business Core indicar ausência de disponibilidade:

- diga isso claramente;
- não invente outras opções;
- não invente outro dia;
- não invente outro profissional.

Você pode sugerir naturalmente uma próxima ação,
como procurar outro período, outro dia ou outro profissional,
quando isso fizer sentido.

=====================================================
CONFIRMAÇÃO DE AGENDAMENTO
=====================================================

Quando o CORE retornar uma confirmação real:

- informe serviço quando útil;
- profissional quando útil;
- data;
- horário;
- preço quando disponível.

A resposta deve transmitir segurança sem parecer um recibo robótico.

Pode ser algo curto e visual.

Exemplo de lógica:

"Fechado ✂️
Seu corte com Pedro ficou marcado para amanhã às 14h30.
Valor: R$ 30."

Mas adapte ao estilo do cliente.

Não copie o exemplo literalmente.

=====================================================
ERROS OPERACIONAIS
=====================================================

Se execution indicar erro:

- não revele stack trace;
- não revele códigos internos;
- não mencione PostgreSQL;
- não mencione n8n;
- não mencione nomes de funções internas.

Explique apenas o necessário em linguagem humana.

Quando possível, ofereça um próximo passo útil.

=====================================================
CONTINUIDADE
=====================================================

Responda como continuação da conversa.

Não recomece o atendimento.

Não repita informações já conhecidas sem necessidade.

Use:

- original_message;
- interpreted_command;
- recent_messages;
- customer;
- brand;
- core_execution;
- clock.

Exemplo:

Se o cliente já pediu corte com Pedro amanhã,
não precisa repetir uma explicação longa sobre serviço e profissional.

=====================================================
PREÇO E DURAÇÃO
=====================================================

Mencione preço ou duração quando forem úteis para a decisão.

Não é obrigatório repetir preço em todas as mensagens.

Evite sobrecarregar a resposta com informação que o cliente não precisa naquele momento.

=====================================================
TAMANHO
=====================================================

Prefira mensagens curtas ou médias.

WhatsApp não deve parecer um relatório.

Use apenas o tamanho necessário para resolver aquele turno.

=====================================================
SAÍDA
=====================================================

Retorne SOMENTE o objeto estruturado solicitado pelo JSON Schema.

O campo text deve conter exclusivamente a mensagem final destinada ao cliente.

Não explique sua lógica interna.

Não use Markdown técnico.

Não acrescente campos fora do schema.
`;


// ======================================================
// INPUT DO RESPONSE ENGINE
// ======================================================

return {
  json: {

    response_request: {

      system_instruction:
        systemInstruction,

      input: {

        original_message:
          originalInput.message?.normalized_text
          ?? originalInput.message?.text
          ?? null,

        interpreted_command:
          validated,

        core_execution:
          execution,

        recent_messages:
          context.recent_messages
          ?? [],

        business: {

          name:
            context.business?.name
            ?? null,

          timezone:
            context.business?.timezone
            ?? null,

          locale:
            context.business?.locale
            ?? 'pt-BR'
        },

        brand:
          context.brand
          ?? {},

        customer: {

          name:
            context.customer?.name
            ?? null,

          communication_profile:
            context.customer?.communication_profile
            ?? {},

          preferences:
            context.customer?.preferences
            ?? {}
        },

        clock:
          context.clock
          ?? {}
      }
    }
  }
};

const item = $json;

const validated =
  $('05 - VALIDAR COMANDO IA').item.json.validated_command ?? {};

let text = null;
let responseType = 'GENERAL';
let shouldSend = true;
let source = null;


// ======================================================
// CAMINHO 1 — RESPOSTA DIRETA DA IA ORQUESTRADORA
// ======================================================

if (
  item.validated_command
  && item.validated_command.direct_response
) {

  text =
    item.validated_command.direct_response;

  source =
    'ORCHESTRATOR_DIRECT';


  if (
    item.validated_command.kind === 'NEED_INFORMATION'
  ) {
    responseType = 'QUESTION';

  } else if (
    item.validated_command.kind === 'HUMAN_HANDOFF'
  ) {
    responseType = 'HANDOFF';

  } else {
    responseType = 'INFORMATION';
  }
}


// ======================================================
// CAMINHO 2 — RESPOSTA GERADA PELO RESPONSE ENGINE
// ======================================================

else {

  let response =
    item.output?.[0]?.content
      ?.find(content => content.type === 'output_text')
      ?.text
    ?? null;


  // Dependendo do node OpenAI, pode chegar
  // como string JSON ou objeto já parseado.
  if (typeof response === 'string') {

    try {
      response =
        JSON.parse(response);
    } catch {
      text = response;
      response = null;
    }
  }


  if (
    response
    && typeof response === 'object'
  ) {

    text =
      response.text
      ?? null;

    responseType =
      response.response_type
      ?? 'GENERAL';

    shouldSend =
      response.should_send !== false;
  }


  source =
    'RESPONSE_ENGINE';
}


// ======================================================
// SEGURANÇA
// ======================================================

if (
  !text
  || typeof text !== 'string'
  || !text.trim()
) {

  return {
    json: {
      final_response: {
        valid: false,
        should_send: false,
        text: null,
        response_type: 'ERROR',
        source,
        error: 'EMPTY_FINAL_RESPONSE'
      }
    }
  };
}


// ======================================================
// SAÍDA CANÔNICA
// ======================================================

return {
  json: {

    final_response: {

      valid: true,

      should_send:
        shouldSend,

      text:
        text.trim(),

      response_type:
        responseType,

      source,

      route:
        validated.route
        ?? null,

      kind:
        validated.kind
        ?? null,

      intent:
        validated.intent
        ?? null
    }
  }
};;

const finalization =
  $('10 - FINALIZAR TURNO').item.json.finalization ?? {};

const context =
  $('02 - CARREGAR CONTEXTO CORE').item.json.context ?? {};

const finalResponse =
  $('09 - NORMALIZAR RESPOSTA FINAL').item.json.final_response ?? {};


// ======================================================
// DADOS BÁSICOS
// ======================================================

const outboundMessageId =
  finalization.outbound_message_id
  ?? finalization.outbound?.message_id
  ?? null;

const recipient =
  context.customer?.external_user_id
  ?? null;

const phoneNumberId =
  context.channel?.external_channel_id
  ?? null;

const text =
  String(
    finalResponse.text
    ?? ''
  ).trim();

const responseType =
  finalResponse.response_type
  ?? 'GENERAL';


const errors = [];

if (!outboundMessageId) {
  errors.push('OUTBOUND_MESSAGE_ID_MISSING');
}

if (!recipient) {
  errors.push('RECIPIENT_MISSING');
}

if (!phoneNumberId) {
  errors.push('PHONE_NUMBER_ID_MISSING');
}

if (!text) {
  errors.push('TEXT_MISSING');
}


// ======================================================
// HELPERS
// ======================================================

function money(value, currency = 'BRL') {

  if (
    value === null
    || value === undefined
    || Number.isNaN(Number(value))
  ) {
    return null;
  }

  try {

    return new Intl.NumberFormat(
      'pt-BR',
      {
        style: 'currency',
        currency
      }
    ).format(Number(value));

  } catch {

    return `R$ ${Number(value).toFixed(2)}`;
  }
}


function trimText(value, max) {

  const str =
    String(value ?? '').trim();

  if (str.length <= max) {
    return str;
  }

  return str.slice(0, max - 1).trim() + '…';
}


// ======================================================
// PADRÃO: MENSAGEM DE TEXTO
// ======================================================

let sendMode =
  'TEXT';

let metaPayload = {

  messaging_product:
    'whatsapp',

  recipient_type:
    'individual',

  to:
    recipient,

  type:
    'text',

  text: {

    preview_url:
      false,

    body:
      text
  }
};


let interactiveMetadata =
  null;


// ======================================================
// SLOT OPTIONS
// ======================================================

if (
  responseType === 'SLOT_OPTIONS'
) {

  let execution = {};

  try {

    execution =
      $('06 - EXECUTAR AÇÃO CORE')
        .item
        .json
        .execution
      ?? {};

  } catch {
    execution = {};
  }


  const result =
    execution.result ?? {};

  const slots =
    Array.isArray(result.slots)
      ? result.slots
      : [];

  const slotOfferId =
    result.slot_offer_id
    ?? null;


  if (
    execution.ok === true
    && slotOfferId
    && slots.length > 0
  ) {

    // ==================================================
    // ATÉ 3 OPÇÕES → BOTÕES DIRETOS
    // ==================================================

    if (slots.length <= 3) {

      sendMode =
        'INTERACTIVE_BUTTONS';


      const buttons =
        slots.map(
          (slot, index) => {

            const optionNumber =
              index + 1;

            const time =
              slot.local_start
              ?? '';

            return {

              type:
                'reply',

              reply: {

                id:
                  `slot|${slotOfferId}|${optionNumber}`,

                title:
                  trimText(
                    time,
                    20
                  )
              }
            };
          }
        );


      metaPayload = {

        messaging_product:
          'whatsapp',

        recipient_type:
          'individual',

        to:
          recipient,

        type:
          'interactive',

        interactive: {

          type:
            'button',

          body: {

            text:
              trimText(
                text,
                1024
              )
          },

          action: {
            buttons
          }
        }
      };

    }


    // ==================================================
    // 4+ OPÇÕES → LISTA INTERATIVA
    // ==================================================

    else {

      sendMode =
        'INTERACTIVE_LIST';


      const rows =
        slots
          .slice(0, 10)
          .map(
            (slot, index) => {

              const optionNumber =
                index + 1;

              const time =
                slot.local_start
                ?? `Opção ${optionNumber}`;

              const professional =
                slot.professional_name
                ?? '';

              const price =
                money(
                  slot.total_price,
                  slot.currency
                  ?? 'BRL'
                );

              const duration =
                slot.total_service_minutes
                  ? `${slot.total_service_minutes} min`
                  : null;


              const descriptionParts =
                [
                  professional,
                  price,
                  duration
                ]
                .filter(Boolean);


              return {

                id:
                  `slot|${slotOfferId}|${optionNumber}`,

                title:
                  trimText(
                    time,
                    24
                  ),

                description:
                  trimText(
                    descriptionParts.join(' • '),
                    72
                  )
              };
            }
          );


      metaPayload = {

        messaging_product:
          'whatsapp',

        recipient_type:
          'individual',

        to:
          recipient,

        type:
          'interactive',

        interactive: {

          type:
            'list',

          header: {

            type:
              'text',

            text:
              'Horários disponíveis'
          },

          body: {

            text:
              trimText(
                text,
                1024
              )
          },

          footer: {

            text:
              'Escolha o horário que funcionar melhor.'
          },

          action: {

            button:
              'Escolher horário',

            sections: [

              {

                title:
                  'Opções',

                rows
              }
            ]
          }
        }
      };

    }


    interactiveMetadata = {

      type:
        sendMode,

      slot_offer_id:
        slotOfferId,

      option_count:
        slots.length
    };
  }
}


// ======================================================
// OUTPUT
// ======================================================

return {
  json: {

    whatsapp_send: {

      valid:
        errors.length === 0,

      errors,

      internal_message_id:
        outboundMessageId,

      provider:
        context.channel?.provider
        ?? 'META',

      channel_type:
        context.channel?.channel_type
        ?? 'WHATSAPP',

      phone_number_id:
        phoneNumberId,

      recipient,

      send_mode:
        sendMode,

      text,

      interactive:
        interactiveMetadata,

      meta_payload:
        metaPayload
    }
  }
};

const send =
  $('11 - PREPARAR ENVIO WHATSAPP').item.json.whatsapp_send ?? {};

if (send.valid !== true) {
  return {
    json: {
      meta_send_result: {
        ok: false,
        code: 'INVALID_WHATSAPP_SEND_PAYLOAD',
        errors: send.errors ?? []
      }
    }
  };
}

const fakeWamid =
  `wamid.DEV_${Date.now()}`;

return {
  json: {
    meta_send_result: {
      ok: true,

      dev_simulation: true,

      internal_message_id:
        send.internal_message_id,

      provider:
        send.provider,

      external_message_id:
        fakeWamid,

      raw_response: {
        messaging_product: 'whatsapp',

        contacts: [
          {
            input:
              send.recipient,

            wa_id:
              send.recipient
          }
        ],

        messages: [
          {
            id:
              fakeWamid
          }
        ]
      }
    }
  }
};

const raw = $json;

const message =
  Array.isArray(raw.messages)
    ? raw.messages[0]
    : null;

const contact =
  Array.isArray(raw.contacts)
    ? raw.contacts[0]
    : null;


// ======================================================
// VALIDAR EVENTO
// ======================================================

if (!message) {
  return {
    json: {
      event_type: 'UNSUPPORTED_EVENT',
      raw_payload: raw
    }
  };
}


// ======================================================
// TIMESTAMP
// ======================================================

let providerTimestamp = null;

if (message.timestamp) {

  const unix =
    Number(message.timestamp);

  if (
    Number.isFinite(unix)
    && unix > 0
  ) {
    providerTimestamp =
      new Date(unix * 1000).toISOString();
  }
}

providerTimestamp =
  providerTimestamp
  ?? new Date().toISOString();


// ======================================================
// IDENTIDADE DO CLIENTE
// ======================================================

const externalUserId =
  contact?.wa_id
  ?? message.from
  ?? null;

const profileName =
  contact?.profile?.name
  ?? null;


// ======================================================
// CONTEÚDO
// ======================================================

const originalType =
  String(
    message.type
    ?? 'unknown'
  ).toLowerCase();

let text = null;

let interaction = null;

let media = {
  id: null,
  mime_type: null,
  url: null,
  caption: null,
  filename: null
};


// ======================================================
// TEXTO
// ======================================================

if (originalType === 'text') {

  text =
    message.text?.body
    ?? null;
}


// ======================================================
// INTERACTIVE
// ======================================================

if (originalType === 'interactive') {

  const interactiveType =
    message.interactive?.type
    ?? null;


  // ----------------------------------------------------
  // LIST REPLY
  // ----------------------------------------------------

  if (interactiveType === 'list_reply') {

    const reply =
      message.interactive?.list_reply
      ?? {};

    const replyId =
      reply.id
      ?? null;

    let slotOfferId = null;
    let optionNumber = null;


    if (
      typeof replyId === 'string'
      && replyId.startsWith('slot|')
    ) {

      const parts =
        replyId.split('|');

      if (
        parts.length === 3
        && parts[0] === 'slot'
      ) {

        slotOfferId =
          parts[1]
          ?? null;

        const parsedOption =
          Number(parts[2]);

        if (
          Number.isInteger(parsedOption)
          && parsedOption >= 1
        ) {
          optionNumber =
            parsedOption;
        }
      }
    }


    interaction = {

      kind:
        'LIST_REPLY',

      action:
        slotOfferId && optionNumber
          ? 'SELECT_SLOT'
          : null,

      reply_id:
        replyId,

      title:
        reply.title
        ?? null,

      description:
        reply.description
        ?? null,

      slot_offer_id:
        slotOfferId,

      option_number:
        optionNumber
    };


    // Texto humano também fica disponível para histórico/IA.
    text =
      reply.title
      ?? null;
  }


  // ----------------------------------------------------
  // BUTTON REPLY
  // ----------------------------------------------------

  else if (interactiveType === 'button_reply') {

    const reply =
      message.interactive?.button_reply
      ?? {};

    const replyId =
      reply.id
      ?? null;

    let slotOfferId = null;
    let optionNumber = null;


    if (
      typeof replyId === 'string'
      && replyId.startsWith('slot|')
    ) {

      const parts =
        replyId.split('|');

      if (
        parts.length === 3
        && parts[0] === 'slot'
      ) {

        slotOfferId =
          parts[1]
          ?? null;

        const parsedOption =
          Number(parts[2]);

        if (
          Number.isInteger(parsedOption)
          && parsedOption >= 1
        ) {
          optionNumber =
            parsedOption;
        }
      }
    }


    interaction = {

      kind:
        'BUTTON_REPLY',

      action:
        slotOfferId && optionNumber
          ? 'SELECT_SLOT'
          : null,

      reply_id:
        replyId,

      title:
        reply.title
        ?? null,

      slot_offer_id:
        slotOfferId,

      option_number:
        optionNumber
    };


    text =
      reply.title
      ?? null;
  }
}


// ======================================================
// ÁUDIO
// ======================================================

if (originalType === 'audio') {

  media = {
    ...media,

    id:
      message.audio?.id
      ?? null,

    mime_type:
      message.audio?.mime_type
      ?? null
  };
}


// ======================================================
// IMAGEM
// ======================================================

if (originalType === 'image') {

  media = {
    ...media,

    id:
      message.image?.id
      ?? null,

    mime_type:
      message.image?.mime_type
      ?? null,

    caption:
      message.image?.caption
      ?? null
  };

  text =
    message.image?.caption
    ?? null;
}


// ======================================================
// DOCUMENTO
// ======================================================

if (originalType === 'document') {

  media = {
    ...media,

    id:
      message.document?.id
      ?? null,

    mime_type:
      message.document?.mime_type
      ?? null,

    caption:
      message.document?.caption
      ?? null,

    filename:
      message.document?.filename
      ?? null
  };

  text =
    message.document?.caption
    ?? null;
}


// ======================================================
// VÍDEO
// ======================================================

if (originalType === 'video') {

  media = {
    ...media,

    id:
      message.video?.id
      ?? null,

    mime_type:
      message.video?.mime_type
      ?? null,

    caption:
      message.video?.caption
      ?? null
  };

  text =
    message.video?.caption
    ?? null;
}


// ======================================================
// OUTPUT CANÔNICO
// ======================================================

return {
  json: {

    event_type:
      'INBOUND_MESSAGE',

    dev:
      false,

    /*
     * TEMPORÁRIO DURANTE O TESTE DA BARBEARIA.
     *
     * Depois vamos resolver a empresa pelo phone_number_id
     * cadastrado em business_channels, sem hardcode.
     */
    business_code:
      'BARB001',

    channel: {

      type:
        'WHATSAPP',

      provider:
        'META',

      external_channel_id:
        raw.metadata?.phone_number_id
        ?? null
    },

    customer: {

      external_user_id:
        externalUserId,

      profile_name:
        profileName
    },

    message: {

      external_message_id:
        message.id
        ?? null,

      idempotency_key:
        message.id
          ? `IN:META:${message.id}`
          : null,

      type:
        originalType,

      text,

      interaction,

      media,

      reply_to_external_message_id:
        message.context?.id
        ?? null,

      provider_timestamp:
        providerTimestamp,

      raw_payload:
        raw
    },

    received_at:
      new Date().toISOString()
  }
};

const input =
  $('01 - NORMALIZAR ENTRADA').first().json;

const context =
  $('02 - CARREGAR CONTEXTO CORE').first().json.context ?? {};

const interaction =
  input.message?.interaction ?? null;


// ======================================================
// HELPERS
// ======================================================

const emptyArguments = () => ({
  service_id: null,
  professional_id: null,
  date: null,
  period: null,
  time: null,
  time_from: null,
  time_until: null,
  option_number: null,
  appointment_id: null,
  allow_professional_fallback: false
});


const UUID_REGEX =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;


// ======================================================
// HELPER - REBOOK A PARTIR DO CONTEXTO
// ======================================================
//
// Usado quando uma lista de horários expirou durante
// um fluxo de reagendamento iniciado por cancelamento.
//
// NÃO confiamos em serviço, profissional ou horário
// armazenados no contexto.
//
// A única referência operacional é appointment_id.
//
// O CORE continuará responsável por validar:
// - empresa
// - cliente
// - ownership
// - status CANCELLED
// - ator do cancelamento
// - profissional
// - serviços
// - disponibilidade
// ======================================================

const buildRebookFromContext = () => {

  const rebooking =
    context.conversation?.context?.rebooking
    ?? null;

  const appointmentId =
    rebooking?.source_appointment_id
    ?? null;


  if (
    !appointmentId
    || typeof appointmentId !== 'string'
    || !UUID_REGEX.test(appointmentId)
  ) {
    return null;
  }


  return {
    json: {
      structured_command: {

        kind:
          'BUSINESS_ACTION',

        intent:
          'REBOOK_APPOINTMENT',

        action:
          'REBOOK_APPOINTMENT',

        arguments: {
          ...emptyArguments(),

          appointment_id:
            appointmentId
        },

        missing_information:
          [],

        customer_meaning:
          'A lista anterior de horários expirou durante o reagendamento. O cliente continua querendo outro horário para o agendamento cancelado.',

        direct_response:
          null,

        confidence:
          1
      }
    }
  };
};


// ======================================================
// VALIDAR EXISTÊNCIA DA INTERAÇÃO
// ======================================================

if (!interaction) {
  return {
    json: {
      structured_command: {

        kind:
          'NEED_INFORMATION',

        intent:
          'OTHER',

        action:
          'NONE',

        arguments:
          emptyArguments(),

        missing_information: [
          'CLARIFICATION'
        ],

        customer_meaning:
          'Interação estruturada não reconhecida.',

        direct_response:
          'Não consegui identificar essa opção. Pode tentar novamente?',

        confidence:
          1
      }
    }
  };
}


// ======================================================
// IDENTIFICAR TIPO DE AÇÃO ESTRUTURADA
// ======================================================

const replyId =
  typeof interaction.reply_id === 'string'
    ? interaction.reply_id.trim()
    : '';

const isSelectSlot =
  interaction.action === 'SELECT_SLOT';

const isRebook =
  replyId.startsWith('rebook|');


// ======================================================
// REBOOK DE AGENDAMENTO CANCELADO
// ======================================================

if (isRebook) {

  const parts =
    replyId.split('|');

  const appointmentId =
    parts.length === 2
      ? parts[1]
      : null;


  // ----------------------------------------------------
  // VALIDAR FORMATO
  // ----------------------------------------------------

  if (
    !appointmentId
    || !UUID_REGEX.test(appointmentId)
  ) {
    return {
      json: {
        structured_command: {

          kind:
            'NEED_INFORMATION',

          intent:
            'REBOOK_APPOINTMENT',

          action:
            'NONE',

          arguments:
            emptyArguments(),

          missing_information: [
            'APPOINTMENT'
          ],

          customer_meaning:
            'Cliente clicou em um botão de reagendamento inválido.',

          direct_response:
            'Não consegui identificar o agendamento que você quer remarcar. Posso te ajudar a procurar outro horário.',

          confidence:
            1
        }
      }
    };
  }


  // ----------------------------------------------------
  // NÃO CONFIAR NO CONTEXTO ANTIGO DE BOOKING.
  //
  // O appointment_id é a referência determinística.
  //
  // O CORE validará:
  // - empresa
  // - cliente
  // - status
  // - cancelamento
  // - profissional
  // - serviços
  // ----------------------------------------------------

  return {
    json: {
      structured_command: {

        kind:
          'BUSINESS_ACTION',

        intent:
          'REBOOK_APPOINTMENT',

        action:
          'REBOOK_APPOINTMENT',

        arguments: {
          ...emptyArguments(),

          appointment_id:
            appointmentId
        },

        missing_information:
          [],

        customer_meaning:
          'Cliente quer procurar um novo horário a partir do agendamento cancelado.',

        direct_response:
          null,

        confidence:
          1
      }
    }
  };
}


// ======================================================
// SELECT_SLOT
// ======================================================

if (isSelectSlot) {

  const activeOffer =
    context.active_offer
    ?? null;

  const clickedOfferId =
    typeof interaction.slot_offer_id === 'string'
      ? interaction.slot_offer_id.trim()
      : null;

  const optionNumber =
    interaction.option_number
    ?? null;


  // ====================================================
  // VALIDAR IDENTIFICADOR DA OFERTA CLICADA
  // ====================================================

  if (
    !clickedOfferId
    || !UUID_REGEX.test(clickedOfferId)
  ) {
    return {
      json: {
        structured_command: {

          kind:
            'NEED_INFORMATION',

          intent:
            'SELECT_SLOT',

          action:
            'NONE',

          arguments:
            emptyArguments(),

          missing_information: [
            'SLOT_OFFER'
          ],

          customer_meaning:
            'Cliente clicou em uma opção cujo identificador da oferta é inválido.',

          direct_response:
            'Não consegui identificar essa lista de horários. Posso buscar opções atualizadas pra você.',

          confidence:
            1
        }
      }
    };
  }


  // ====================================================
  // NÃO EXISTE MAIS OFERTA ATIVA
  //
  // A lista expirou.
  //
  // Se estivermos dentro de um fluxo de rebooking,
  // regeneramos a oferta automaticamente.
  // ====================================================

  if (!activeOffer) {

    const automaticRebook =
      buildRebookFromContext();


    if (automaticRebook) {
      return automaticRebook;
    }


    // --------------------------------------------------
    // Não existe contexto suficiente para regenerar
    // deterministicamente.
    // --------------------------------------------------

    return {
      json: {
        structured_command: {

          kind:
            'CONVERSATION',

          intent:
            'SELECT_SLOT',

          action:
            'NONE',

          arguments:
            emptyArguments(),

          missing_information:
            [],

          customer_meaning:
            'Cliente selecionou uma opção de uma oferta que expirou e não há contexto suficiente para regenerá-la automaticamente.',

          direct_response:
            'Essa lista já não está mais ativa. Me diga o dia ou horário que você procura e eu verifico novamente.',

          confidence:
            1
        }
      }
    };
  }


  // ====================================================
  // EXISTE OFERTA ATIVA, MAS O CLIENTE CLICOU EM OUTRA
  //
  // Isso pode ocorrer quando:
  // - existe uma lista antiga na conversa;
  // - uma nova oferta já foi criada depois;
  // - o cliente clicou na mensagem antiga.
  //
  // NÃO criamos outra oferta aqui para evitar:
  // - múltiplas ofertas concorrentes;
  // - invalidar uma oferta recém-criada;
  // - loops de regeneração.
  // ====================================================

  if (
    activeOffer.slot_offer_id !== clickedOfferId
  ) {
    return {
      json: {
        structured_command: {

          kind:
            'CONVERSATION',

          intent:
            'SELECT_SLOT',

          action:
            'NONE',

          arguments:
            emptyArguments(),

          missing_information:
            [],

          customer_meaning:
            'Cliente clicou em uma lista antiga enquanto já existe uma oferta de horários mais recente ativa.',

          direct_response:
            'Essa lista é antiga. Use a lista de horários mais recente que enviei pra você.',

          confidence:
            1
        }
      }
    };
  }


  // ====================================================
  // VALIDAR OPTION_NUMBER
  // ====================================================

  if (
    !Number.isInteger(optionNumber)
    || optionNumber <= 0
  ) {
    return {
      json: {
        structured_command: {

          kind:
            'NEED_INFORMATION',

          intent:
            'SELECT_SLOT',

          action:
            'NONE',

          arguments:
            emptyArguments(),

          missing_information: [
            'SLOT_OPTION'
          ],

          customer_meaning:
            'Cliente clicou em uma opção com número inválido.',

          direct_response:
            'Não consegui identificar esse horário. Pode escolher uma opção da lista novamente.',

          confidence:
            1
        }
      }
    };
  }


  // ====================================================
  // VALIDAR OPÇÃO
  // ====================================================

  const selectedOption =
    Array.isArray(activeOffer.options)
      ? activeOffer.options.find(
          option =>
            option.option_number === optionNumber
        )
      : null;


  if (!selectedOption) {
    return {
      json: {
        structured_command: {

          kind:
            'NEED_INFORMATION',

          intent:
            'SELECT_SLOT',

          action:
            'NONE',

          arguments:
            emptyArguments(),

          missing_information: [
            'SLOT_OPTION'
          ],

          customer_meaning:
            'Cliente clicou em uma opção que não existe na oferta ativa.',

          direct_response:
            'Essa opção não está mais disponível. Pode escolher outro horário da lista.',

          confidence:
            1
        }
      }
    };
  }


  // ====================================================
