parameters.jsCode:
const items = $input.all();

const sync =
  $('14 - PREPARAR CALENDAR SYNC').first().json.calendar_sync;

const appointmentId =
  sync?.appointment?.appointment_id ?? null;

if (!appointmentId) {
  return [
    {
      json: {
        route: 'ERROR',
        error: 'APPOINTMENT_ID_MISSING'
      }
    }
  ];
}


// ======================================================
// PROCURAR EVENTO REALMENTE CORRESPONDENTE
// ======================================================

const marker =
  `Appointment ID: ${appointmentId}`;

const matchingEvent =
  items
    .map(item => item.json ?? {})
    .find(event => {

      const description =
        String(event.description ?? '');

      const eventId =
        event.id ?? null;

      const status =
        String(event.status ?? '').toLowerCase();

      return (
        eventId
        && description.includes(marker)
        && status !== 'cancelled'
      );
    });


// ======================================================
// EVENTO JÁ EXISTE NO GOOGLE
// ======================================================

if (matchingEvent) {

  return [
    {
      json: {
        route:
          'FOUND',

        id:
          matchingEvent.id,

        reconciliation: {
          code:
            'EXISTING_GOOGLE_EVENT_FOUND',

          appointment_id:
            appointmentId,

          external_event_id:
            matchingEvent.id
        },

        event:
          matchingEvent
      }
    }
  ];
}


// ======================================================
// NÃO EXISTE → PODE CRIAR
// ======================================================

return [
  {
    json: {
      route:
        'CREATE',

      reconciliation: {
        code:
          'GOOGLE_EVENT_NOT_FOUND',

        appointment_id:
          appointmentId
      }
    }
  }
];

